/**
 * Format confidence score as human-readable label.
 */
function formatConfidence(score) {
    if (score == null)
        return "";
    if (score >= 0.8)
        return "[high match] ";
    if (score >= 0.5)
        return "[medium match] ";
    return "[low match] ";
}
/**
 * Format memory age as human-readable label.
 */
function formatAge(createdAt) {
    if (!createdAt)
        return "";
    const now = new Date();
    const created = new Date(createdAt);
    const diffMs = now.getTime() - created.getTime();
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    if (diffDays < 1)
        return "today";
    if (diffDays === 1)
        return "yesterday";
    if (diffDays < 7)
        return `${diffDays} days ago`;
    if (diffDays < 30)
        return `${Math.floor(diffDays / 7)} weeks ago`;
    if (diffDays < 365)
        return `${Math.floor(diffDays / 30)} months ago`;
    return `${Math.floor(diffDays / 365)} years ago`;
}
/**
 * Format recalled memories as a markdown block for injection into the conversation.
 */
export function formatMemoriesForInjection(memories) {
    if (memories.length === 0)
        return "";
    const lines = memories.map((m) => {
        const confidence = formatConfidence(m.score);
        const age = formatAge(m.created_at);
        const ageLabel = age ? ` (${age})` : "";
        const type = m.memory_type ? ` [${m.memory_type}]` : "";
        return `- ${confidence}${m.content}${type}${ageLabel}`;
    });
    return `[MEMORY] Relevant Memories (auto-injected by memory plugin):\n${lines.join("\n")}`;
}
/**
 * Format project knowledge memories for full injection (not query-dependent).
 * These are the most recent valid memories, injected regardless of semantic match.
 */
export function formatProjectKnowledge(memories) {
    if (memories.length === 0)
        return "";
    const lines = memories.map((m) => {
        const type = m.memory_type ? ` (${m.memory_type})` : "";
        return `- ${m.content}${type}`;
    });
    return `[MEMORY] Project Knowledge (session guidance):\n${lines.join("\n")}`;
}
/**
 * Format memories for compaction recovery — includes more context.
 */
export function formatMemoriesForRecovery(taskMemories, contextMemories) {
    const sections = [];
    if (taskMemories.length > 0) {
        sections.push("## Task state", ...taskMemories.map((m) => `- ${m.content}`));
    }
    if (contextMemories.length > 0) {
        sections.push("## Recovery additions", ...contextMemories.map((m) => `- ${m.content}`));
    }
    if (sections.length === 0)
        return "";
    return `[MEMORY RECOVERY] Additive context not already covered by compact summary:\n${sections.join("\n")}`;
}
function tierLabel(tier) {
    if (tier.categories.length === 0)
        return "Other";
    return tier.categories.join(" / ");
}
export function formatTieredProjectKnowledge(allocated, tiers) {
    const sections = [];
    for (let i = 0; i < tiers.length; i++) {
        const memories = allocated.get(i) ?? [];
        if (memories.length === 0)
            continue;
        const label = tierLabel(tiers[i]);
        sections.push(`### ${label}`);
        for (const m of memories) {
            const type = m.memory_type ? ` (${m.memory_type})` : "";
            sections.push(`- ${m.content}${type}`);
        }
    }
    if (sections.length === 0)
        return "";
    return `[MEMORY] Project Knowledge (tiered session guidance):\n${sections.join("\n")}`;
}
export function formatKnowledgeGraph(communities, maxItems) {
    if (!communities || communities.length === 0)
        return "";
    const sections = [];
    for (const community of communities.slice(0, maxItems)) {
        sections.push(`## ${community.label} (${community.size} entities)`);
        for (const entity of community.entities.slice(0, 3)) {
            const type = entity.entity_type ? ` [${entity.entity_type}]` : "";
            sections.push(`  - ${entity.name}${type}`);
        }
    }
    if (sections.length === 0)
        return "";
    return `[KNOWLEDGE GRAPH] Architectural Overview:\n${sections.join("\n")}`;
}
